package com.bank.reference;

import java.util.*;
import java.util.logging.*;

public class ReferenceDemo {
    private static final Logger log = Logger.getLogger("Reference");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        ReferenceService service = new ReferenceService();

        List<String> refs = service.generateReferences(5);
        log.info(() -> "Generated " + refs.size() + " references");
        refs.forEach(r -> log.info(() -> "  " + r));
        log.info(() -> "All unique: " + (new HashSet<>(refs).size() == refs.size()));
    }
}

// ─── Would be in service/ReferenceService.java ───
class ReferenceService {
    // generate() calls the supplier afresh each time — independent values
    List<String> generateReferences(int count) {
        return java.util.stream.Stream
            .generate(() -> "TXN-" + UUID.randomUUID())  // fresh value every call
            .limit(count)                                 // bound the infinite stream
            .collect(java.util.stream.Collectors.toList());
    }
}
